+
+        c_result = torch.empty(c.size(), dtype=dtype, device=device)
+
+        # Checking out variant
+        torch._int_mm(a_int8, b_int8, out_dtype=dtype, out=c_result)
+        self.assertEqual(c_result, torch.mm(a_float, b_float).to(dtype))
